public class CharAt {
public static void main(String[] args) {
    String name = "flevia";

    char firstchar = name.charAt(0);
    char thirdchar = name.charAt(2);

    System.out.println("firstcharcter :" + firstchar);
    System.out.println("thirdcharcter :" + thirdchar);

}

